import pandas as pd


def run(inputs: dict) -> dict:
    # Handle case-insensitive / flexible key lookup for the input relation
    ledger = None
    for key in ('LEDGER', 'ledger', 'Ledger'):
        if key in inputs:
            ledger = inputs[key].copy()
            break
    if ledger is None:
        # fallback: find any key matching case-insensitively
        for k, v in inputs.items():
            if k.lower() == 'ledger':
                ledger = v.copy()
                break
    if ledger is None:
        raise KeyError('LEDGER input not found')

    # Sort by account_id, entry_date, row_seq (stable sort preserves cursor order)
    ledger = ledger.sort_values(
        by=['account_id', 'entry_date', 'row_seq'], kind='mergesort'
    ).reset_index(drop=True)

    records = []
    prev_acct = None
    bal = 0.0
    cyc = 1

    for _, row in ledger.iterrows():
        acct = row['account_id']

        if acct != prev_acct:
            bal = 0.0
            cyc = 1
            prev_acct = acct

        if row['entry_type'] == 'STMT':
            bal = 0.0
            cyc += 1

        amt = row['amount']
        if pd.isna(amt):
            amt = 0.0

        bal = bal + amt

        records.append({
            'account_id': row['account_id'],
            'row_seq': row['row_seq'],
            'entry_date': row['entry_date'],
            'entry_type': row['entry_type'],
            'amount': row['amount'],
            'cycle_no': cyc,
            'cycle_balance': bal,
        })

    out_cols = ['account_id', 'row_seq', 'entry_date', 'entry_type',
                'amount', 'cycle_no', 'cycle_balance']

    cycle_balances = pd.DataFrame(records, columns=out_cols)

    return {'cycle_balances': cycle_balances}
